4: 
5: pragma solidity ^0.8.20;
6: 
7: import {AppStorage} from "../storage/AppStorage.sol";
8: import {LibDiamond} from "../../libraries/LibDiamond.sol";
9: import {LibEth} from "../../libraries/Token/LibEth.sol";
10: import {AdvancedFarmCall, LibFarm} from "../../libraries/LibFarm.sol";
11: import {LibFunction} from "../../libraries/LibFunction.sol";
12: import {Invariable} from "contracts/beanstalk/Invariable.sol";
13: 
14: /**
15:  * @title Farm Facet
16:  * @author Beasley, Publius
17:  * @notice Perform multiple Beanstalk functions calls in a single transaction using Farm calls.
18:  * Any function stored in Beanstalk's EIP-2535 DiamondStorage can be called as a Farm call. (https://eips.ethereum.org/EIPS/eip-2535)
19:  **/
20: 
21: contract FarmFacet is Invariable {
22:     AppStorage internal s;
23: 
24:     /**
25:      * @notice Execute multiple Farm calls.
26:      * @param data The encoded function data for each of the calls
27:      * @return results The return data from each of the calls
28:      **/
29:     function farm(
30:         bytes[] calldata data
31:     ) external payable fundsSafu withEth returns (bytes[] memory results) {
32:         results = new bytes[](data.length);
33:         for (uint256 i; i < data.length; ++i) {
34:             results[i] = LibFarm._farm(data[i]);
35:         }
36:     }
37: 
38:     /**
39:      * @notice Execute multiple AdvancedFarmCalls.
40:      * @param data The encoded function data for each of the calls to make to this contract
41:      * See LibFunction.buildAdvancedCalldata for details on advanced data
42:      * @return results The results from each of the calls passed in via data
43:      **/
44:     function advancedFarm(
45:         AdvancedFarmCall[] calldata data
46:     ) external payable fundsSafu withEth returns (bytes[] memory results) {
47:         results = new bytes[](data.length);
48:         for (uint256 i = 0; i < data.length; ++i) {
49:             results[i] = LibFarm._advancedFarm(data[i], results);
50:         }
51:     }
52: 
53:     // signals to Beanstalk functions that they should not refund Eth
54:     // at the end of the function because the function is wrapped in a Farm function
55:     modifier withEth() {
56:         if (msg.value > 0) s.sys.isFarm = 2;
57:         _;
58:         if (msg.value > 0) {
59:             s.sys.isFarm = 1;
60:             LibEth.refundEth();
61:         }
62:     }
63: }
